fn pipeline_request_to_json(req: PipelineRequest) -> String {
    let mut json = String::new();
    json.push_str("{\"request_id\":\"");
    json.push_str(req.request_id.as_str());
    json.push_str("\",\"tenant_id\":\"");
    json.push_str(req.tenant_id.as_str());
    json.push_str("\",\"user_intent\":\"");
    json.push_str(req.user_intent.as_str());
    json.push_str("\",\"timeout_seconds\":");
    json.push_str(&req.timeout_seconds.to_string());
    json.push_str("}");
    json
}

fn pipeline_response_to_json(resp: PipelineResponse) -> String {
    let mut json = String::new();
    json.push_str("{\"response_id\":\"");
    json.push_str(resp.response_id.as_str());
    json.push_str("\",\"tenant_id\":\"");
    json.push_str(resp.tenant_id.as_str());
    json.push_str("\",\"success\":");
    if resp.success {
        json.push_str("true");
    } else {
        json.push_str("false");
    }
    json.push_str(",\"execution_time_ms\":");
    json.push_str(&resp.execution_time_ms.to_string());
    json.push_str(",\"result\":\"");
    json.push_str(resp.result.as_str());
    json.push_str("\"}");
    json
}

fn metrics_response_to_json(resp: MetricsResponse) -> String {
    let mut json = String::new();
    json.push_str("{\"response_id\":\"");
    json.push_str(resp.response_id.as_str());
    json.push_str("\",\"metric_type\":\"");
    json.push_str(resp.metric_type.as_str());
    json.push_str("\",\"value\":");
    json.push_str(&resp.value.to_string());
    json.push_str(",\"unit\":\"");
    json.push_str(resp.unit.as_str());
    json.push_str("\"}");
    json
}

fn health_check_response_to_json(resp: HealthCheckResponse) -> String {
    let mut json = String::new();
    json.push_str("{\"service_name\":\"");
    json.push_str(resp.service_name.as_str());
    json.push_str("\",\"status\":\"");
    json.push_str(resp.status.as_str());
    json.push_str("\",\"uptime_seconds\":");
    json.push_str(&resp.uptime_seconds.to_string());
    json.push_str("}");
    json
}

