            tenant_id: self.tenant_id.clone(),
            request_body: self.request_body.clone(),
            timeout_seconds: self.timeout_seconds.clone()
        }
    }
}

struct GrpcClientMetadata {
    metadata_entries: Vec<String>,  // "key:value" 형식
    tenant_id: String,
    api_key: String,
    request_id: String
}

trait GrpcClientMetadataCl {
    fn clone(&self) -> GrpcClientMetadata;
}

impl GrpcClientMetadataCl for GrpcClientMetadata {
