        let mut cloned_entries = vec![];
        let mut i = 0i32;
        loop {
            if i >= (self.metadata_entries.len() as i32) { break; }
            cloned_entries.push(self.metadata_entries[(i as usize)].clone());
            i = i + 1i32;
        }

        GrpcClientMetadata {
            metadata_entries: cloned_entries,
            tenant_id: self.tenant_id.clone(),
            api_key: self.api_key.clone(),
            request_id: self.request_id.clone()
        }
    }
}

struct GrpcClient {
    connection: GrpcConnection,
    call_history: Vec<GrpcClientCall>,
    metadata: GrpcClientMetadata,
    pending_calls: i32,
    completed_calls: i32
}

trait GrpcClientCl {
    fn clone(&self) -> GrpcClient;
}

impl GrpcClientCl for GrpcClient {
    fn clone(&self) -> GrpcClient {
        let mut cloned_history = vec![];
        let mut i = 0i32;
        loop {
            if i >= (self.call_history.len() as i32) { break; }
            cloned_history.push(self.call_history[(i as usize)].clone());
            i = i + 1i32;
        }

        GrpcClient {
            connection: self.connection.clone(),
            call_history: cloned_history,
            metadata: self.metadata.clone(),
            pending_calls: self.pending_calls.clone(),
            completed_calls: self.completed_calls.clone()
        }
    }
}

// gRPC 클라이언트 생성
fn create_grpc_client(host: String, port: i32, tenant_id: String, api_key: String) -> GrpcClient {
    let connection = GrpcConnection {
        host: host,
        port: port,
        tenant_id: tenant_id.clone(),
        api_key: api_key.clone(),
        is_connected: false,
        request_count: 0i32
    };

    let metadata = GrpcClientMetadata {
        metadata_entries: vec![],
        tenant_id: tenant_id,
        api_key: api_key,
        request_id: "".to_string()
    };

    GrpcClient {
        connection: connection,
        call_history: vec![],
        metadata: metadata,
        pending_calls: 0i32,
        completed_calls: 0i32
    }
}

// 연결 설정
fn connect_grpc_client(client: GrpcClient) -> GrpcClient {
    GrpcClient {
        connection: GrpcConnection {
            host: client.connection.host.clone(),
            port: client.connection.port,
            tenant_id: client.connection.tenant_id.clone(),
            api_key: client.connection.api_key.clone(),
            is_connected: true,
            request_count: client.connection.request_count
        },
        call_history: client.call_history.clone(),
        metadata: client.metadata.clone(),
        pending_calls: client.pending_calls,
        completed_calls: client.completed_calls
    }
}

// 메타데이터 추가
fn add_metadata(client: GrpcClient, key: String, value: String) -> GrpcClient {
    let mut new_entries = vec![];
    let mut i = 0i32;
    loop {
        if i >= (client.metadata.metadata_entries.len() as i32) { break; }
        new_entries.push(client.metadata.metadata_entries[(i as usize)].clone());
        i = i + 1i32;
    }

    let entry = key.clone() + ":".as_str() + value.as_str();
