fn select_service_round_robin(balancer: ServiceLoadBalancer, service_name: String) -> (ServiceEndpoint, ServiceLoadBalancer) {
    let healthy_services = get_healthy_services(balancer.registry.clone());

    if healthy_services.len() == 0i32 {
        let empty = ServiceEndpoint {
            service_id: "".to_string(),
            service_name: "".to_string(),
            host: "".to_string(),
            port: 0i32,
            status: "unhealthy".to_string(),
            last_heartbeat: "".to_string()
        };
        return (empty, balancer);
    }

    let index = balancer.current_index % (healthy_services.len() as i32);
    let selected = healthy_services[(index as usize)].clone();

    let new_balancer = ServiceLoadBalancer {
        registry: balancer.registry.clone(),
        current_index: (balancer.current_index + 1i32) % (healthy_services.len() as i32),
        request_count: balancer.request_count + 1i32
    };

    (selected, new_balancer)
