    json.push_str("\",\"total_services\":");
    json.push_str(&registry.total_services.to_string());
    json.push_str(",\"healthy_count\":");
    json.push_str(&registry.healthy_count.to_string());
    json.push_str(",\"last_updated\":\"");
    json.push_str(registry.last_updated.as_str());
    json.push_str("\"}");
    json
}

// 레지스트리 목록 조회
fn list_registry_endpoints(registry: ServiceRegistry) -> String {
    let mut json = String::new();
    json.push_str("[");
    let mut first = true;
    let mut i = 0i32;
    loop {
        if i >= (registry.endpoints.len() as i32) { break; }
        let endpoint = registry.endpoints[(i as usize)].clone();
        if !first {
            json.push_str(",");
        }
        json.push_str("{\"service_name\":\"");
        json.push_str(endpoint.service_name.as_str());
        json.push_str("\",\"host\":\"");
        json.push_str(endpoint.host.as_str());
        json.push_str("\",\"port\":");
        json.push_str(&endpoint.port.to_string());
        json.push_str(",\"status\":\"");
        json.push_str(endpoint.status.as_str());
        json.push_str("\"}");
        first = false;
        i = i + 1i32;
    }
    json.push_str("]");
    json
}

