    assert agg.total_points == 0i32;
}

test "metrics_aggregator_add_data_point_increments_count" {
    let agg = create_metrics_aggregator();
    let a2 = add_data_point(agg, "execution_time".to_string(), 125.0f32, "tenant-1".to_string());
    assert a2.total_points == 1i32;
}

test "metrics_aggregator_aggregate_calculates_min_max_avg" {
    let agg = create_metrics_aggregator();
    let a2 = add_data_point(agg, "execution_time".to_string(), 100.0f32, "tenant-1".to_string());
    let a3 = add_data_point(a2, "execution_time".to_string(), 200.0f32, "tenant-1".to_string());

    let metrics = aggregate_metrics(a3, "execution_time".to_string(), "tenant-1".to_string());
    assert metrics.count == 2i32;
    assert metrics.min_value == 100.0f32;
    assert metrics.max_value == 200.0f32;
}

test "aggregated_metrics_to_json_contains_stats" {
    let metrics = AggregatedMetrics {
        tenant_id: "tenant-1".to_string(),
        metric_name: "execution_time".to_string(),
        min_value: 100.0f32,
        max_value: 200.0f32,
        avg_value: 150.0f32,
        sum_value: 300.0f32,
        count: 2i32,
        last_updated: "2026-03-18T12:00:00Z".to_string()
    };
    let json = aggregated_metrics_to_json(metrics);
    assert json.contains("min");
    assert json.contains("max");
    assert json.contains("avg");
