            threshold_percent: self.threshold_percent.clone(),
            unit: self.unit.clone()
        }
    }
}

struct ScaleDecision {
    decision_id: String,
    action: String,  // "scale_up" | "scale_down" | "no_action"
    reason: String,
    target_instances: i32,
    current_instances: i32,
    estimated_improvement: f32
}

trait ScaleDecisionCl {
    fn clone(&self) -> ScaleDecision;
}

impl ScaleDecisionCl for ScaleDecision {
