            current_instances: self.current_instances.clone(),
            estimated_improvement: self.estimated_improvement.clone()
        }
    }
}

struct AutoScaler {
    tenant_id: String,
    min_instances: i32,
    max_instances: i32,
    current_instances: i32,
    resource_metrics: Vec<ResourceMetric>,
    scale_history: Vec<ScaleDecision>,
    last_scale_action: String,
    scaling_enabled: bool
}

trait AutoScalerCl {
    fn clone(&self) -> AutoScaler;
}

impl AutoScalerCl for AutoScaler {
    fn clone(&self) -> AutoScaler {
        let mut cloned_metrics = vec![];
        let mut i = 0i32;
        loop {
            if i >= (self.resource_metrics.len() as i32) { break; }
            cloned_metrics.push(self.resource_metrics[(i as usize)].clone());
            i = i + 1i32;
        }

        let mut cloned_history = vec![];
        let mut j = 0i32;
        loop {
            if j >= (self.scale_history.len() as i32) { break; }
            cloned_history.push(self.scale_history[(j as usize)].clone());
            j = j + 1i32;
        }

        AutoScaler {
