            last_scale_action: self.last_scale_action.clone(),
            scaling_enabled: self.scaling_enabled.clone()
        }
    }
}

struct LoadBalancerConfig {
    algorithm: String,  // "round_robin" | "least_connections" | "weighted"
    health_check_interval_seconds: i32,
    connection_timeout_seconds: i32,
    max_connections_per_instance: i32
}

trait LoadBalancerConfigCl {
    fn clone(&self) -> LoadBalancerConfig;
}

impl LoadBalancerConfigCl for LoadBalancerConfig {
    fn clone(&self) -> LoadBalancerConfig {
        LoadBalancerConfig {
            algorithm: self.algorithm.clone(),
            health_check_interval_seconds: self.health_check_interval_seconds.clone(),
            connection_timeout_seconds: self.connection_timeout_seconds.clone(),
            max_connections_per_instance: self.max_connections_per_instance.clone()
        }
    }
}

// 오토스케일러 생성
fn create_autoscaler(tenant_id: String, min: i32, max: i32) -> AutoScaler {
    AutoScaler {
        tenant_id: tenant_id,
        min_instances: min,
        max_instances: max,
        current_instances: min,
        resource_metrics: vec![],
        scale_history: vec![],
        last_scale_action: "initialization".to_string(),
        scaling_enabled: true
    }
}

// 리소스 메트릭 추가
fn add_resource_metric(scaler: AutoScaler, metric_name: String, current: f32, max: f32) -> AutoScaler {
    let metric = ResourceMetric {
        metric_name: metric_name,
        current_usage: current,
        max_capacity: max,
        threshold_percent: 80.0f32,
        unit: "percent".to_string()
    };

    let mut new_metrics = vec![];
    let mut i = 0i32;
    loop {
        if i >= (scaler.resource_metrics.len() as i32) { break; }
        new_metrics.push(scaler.resource_metrics[(i as usize)].clone());
        i = i + 1i32;
    }
    new_metrics.push(metric);

    AutoScaler {
        tenant_id: scaler.tenant_id.clone(),
        min_instances: scaler.min_instances,
        max_instances: scaler.max_instances,
        current_instances: scaler.current_instances,
        resource_metrics: new_metrics,
        scale_history: scaler.scale_history.clone(),
        last_scale_action: scaler.last_scale_action.clone(),
        scaling_enabled: scaler.scaling_enabled
    }
}

// 스케일링 결정
fn evaluate_scaling_decision(scaler: AutoScaler) -> ScaleDecision {
    let mut should_scale_up = false;
    let mut metric_count = 0i32;

    let mut i = 0i32;
    loop {
        if i >= (scaler.resource_metrics.len() as i32) { break; }
        let metric = scaler.resource_metrics[(i as usize)].clone();
        let usage_percent = (metric.current_usage / metric.max_capacity) * 100.0f32;
        if usage_percent > metric.threshold_percent {
            should_scale_up = true;
        }
        metric_count = metric_count + 1i32;
        i = i + 1i32;
    }

    if should_scale_up && scaler.current_instances < scaler.max_instances {
        ScaleDecision {
            decision_id: "decision-001".to_string(),
            action: "scale_up".to_string(),
            reason: "Resource usage exceeded threshold".to_string(),
            target_instances: scaler.current_instances + 1i32,
            current_instances: scaler.current_instances,
            estimated_improvement: 20.0f32
        }
    } else if !should_scale_up && scaler.current_instances > scaler.min_instances {
        ScaleDecision {
            decision_id: "decision-002".to_string(),
            action: "scale_down".to_string(),
            reason: "Resource usage below threshold".to_string(),
            target_instances: scaler.current_instances - 1i32,
            current_instances: scaler.current_instances,
            estimated_improvement: -10.0f32
        }
    } else {
        ScaleDecision {
            decision_id: "decision-003".to_string(),
            action: "no_action".to_string(),
            reason: "Resource usage within acceptable range".to_string(),
            target_instances: scaler.current_instances,
            current_instances: scaler.current_instances,
            estimated_improvement: 0.0f32
        }
    }
}

// 스케일링 결정 적용
fn apply_scale_decision(scaler: AutoScaler, decision: ScaleDecision) -> AutoScaler {
    let mut new_history = vec![];
    let mut i = 0i32;
    loop {
        if i >= (scaler.scale_history.len() as i32) { break; }
        new_history.push(scaler.scale_history[(i as usize)].clone());
        i = i + 1i32;
    }
    new_history.push(decision.clone());

    AutoScaler {
        tenant_id: scaler.tenant_id.clone(),
        min_instances: scaler.min_instances,
        max_instances: scaler.max_instances,
        current_instances: decision.target_instances,
        resource_metrics: scaler.resource_metrics.clone(),
        scale_history: new_history,
        last_scale_action: decision.action.clone(),
        scaling_enabled: scaler.scaling_enabled
    }
}

// 스케일러 상태 조회
fn get_scaler_status(scaler: AutoScaler) -> String {
    let mut json = String::new();
    json.push_str("{\"tenant_id\":\"");
    json.push_str(scaler.tenant_id.as_str());
    json.push_str("\",\"current_instances\":");
    json.push_str(&scaler.current_instances.to_string());
    json.push_str(",\"min_instances\":");
    json.push_str(&scaler.min_instances.to_string());
    json.push_str(",\"max_instances\":");
    json.push_str(&scaler.max_instances.to_string());
    json.push_str(",\"scaling_enabled\":");
    if scaler.scaling_enabled {
        json.push_str("true");
    } else {
        json.push_str("false");
    }
    json.push_str(",\"last_action\":\"");
    json.push_str(scaler.last_scale_action.as_str());
    json.push_str("\"}");
    json
}

// 로드 밸런서 설정 생성
fn create_load_balancer_config(algorithm: String) -> LoadBalancerConfig {
    LoadBalancerConfig {
        algorithm: algorithm,
        health_check_interval_seconds: 10i32,
        connection_timeout_seconds: 30i32,
        max_connections_per_instance: 1000i32
    }
}

// 로드 밸런서 설정 JSON
fn load_balancer_config_to_json(config: LoadBalancerConfig) -> String {
