fn predict_performance(predictor: PerformancePredictor, projected_load: f32) -> PerformancePrediction {
    // 과거 데이터를 바탕으로 선형 보간 (단순화)
    let predicted_response_time = if predictor.historical_data.len() as i32 > 0i32 {
