        recommended_capacity: recommended_capacity,
        upgrade_timeline: "2026-04-18T00:00:00Z".to_string(),
        cost_estimate: ((recommended_capacity - current_capacity) as f32 * 100.0f32)
    }
}

// 용량 계획 적용
fn apply_capacity_plan(predictor: PerformancePredictor, plan: CapacityPlan) -> PerformancePredictor {
    let mut new_plans = vec![];
    let mut i = 0i32;
    loop {
        if i >= (predictor.capacity_plans.len() as i32) { break; }
        new_plans.push(predictor.capacity_plans[(i as usize)].clone());
        i = i + 1i32;
    }
    new_plans.push(plan);

    PerformancePredictor {
        tenant_id: predictor.tenant_id.clone(),
        historical_data: predictor.historical_data.clone(),
        predictions: predictor.predictions.clone(),
        capacity_plans: new_plans,
        model_accuracy: predictor.model_accuracy,
        last_updated: "2026-03-18T12:00:00Z".to_string()
    }
}

// 예측 정확도 계산
fn calculate_prediction_accuracy(predictor: PerformancePredictor) -> f32 {
    let mut total_error = 0.0f32;
    let count = (predictor.predictions.len() as f32) + 1.0f32;

    let mut i = 0i32;
    loop {
        if i >= (predictor.predictions.len() as i32) { break; }
        let pred = predictor.predictions[(i as usize)].clone();
        total_error = total_error + (1.0f32 - pred.confidence_level);
        i = i + 1i32;
    }

    1.0f32 - (total_error / count)
}

// 예측기 통계
fn get_predictor_stats(predictor: PerformancePredictor) -> String {
    let mut json = String::new();
    json.push_str("{\"tenant_id\":\"");
    json.push_str(predictor.tenant_id.as_str());
    json.push_str("\",\"historical_data_points\":");
    json.push_str(&(predictor.historical_data.len() as i32).to_string());
    json.push_str(",\"predictions_made\":");
    json.push_str(&(predictor.predictions.len() as i32).to_string());
    json.push_str(",\"capacity_plans\":");
    json.push_str(&(predictor.capacity_plans.len() as i32).to_string());
    json.push_str(",\"model_accuracy\":");
    json.push_str(&predictor.model_accuracy.to_string());
    json.push_str("}");
    json
}

